package com.servicerca.controller;import com.servicerca.dto.request.*;import com.servicerca.security.SecurityUser;import com.servicerca.service.ServiceRequestService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/requests")public class ServiceRequestController{private final ServiceRequestService service;public ServiceRequestController(ServiceRequestService s){service=s;}@GetMapping public ResponseEntity<List<ServiceRequestResponse>>mine(@AuthenticationPrincipal SecurityUser u){return ResponseEntity.ok(service.mine(u.user()));}@GetMapping("/feed")public ResponseEntity<List<ServiceRequestResponse>>feed(@AuthenticationPrincipal SecurityUser u){return ResponseEntity.ok(service.feed(u.user()));}@PostMapping public ResponseEntity<ServiceRequestResponse>create(@AuthenticationPrincipal SecurityUser u,@Valid@RequestBody CreateServiceRequest r){return ResponseEntity.status(201).body(service.create(u.user(),r));}@PostMapping("/{id}/apply")public ResponseEntity<ServiceRequestResponse>apply(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID id,@Valid@RequestBody ApplyToServiceRequest r){return ResponseEntity.ok(service.apply(u.user(),id,r));}@PostMapping("/{id}/dismiss")public ResponseEntity<Void>dismiss(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID id){service.dismiss(u.user(),id);return ResponseEntity.noContent().build();}@PostMapping("/{requestId}/select/{applicationId}")public ResponseEntity<ServiceRequestResponse>select(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID requestId,@PathVariable UUID applicationId){return ResponseEntity.ok(service.select(u.user(),requestId,applicationId));}@PostMapping("/{id}/start")public ResponseEntity<ServiceRequestResponse>start(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID id){return ResponseEntity.ok(service.start(u.user(),id));}@PostMapping("/{id}/complete")public ResponseEntity<ServiceRequestResponse>complete(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID id){return ResponseEntity.ok(service.complete(u.user(),id));}}
